package com.example.demo;

import org.springframework.stereotype.Service;

@Service
class PrixService {
  int total(int prix, int quantite) {
    if (prix < 0 || quantite < 0) throw new IllegalArgumentException("valeur négative");
    return Math.multiplyExact(prix, quantite);
  }
}

package com.example.demo;

import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
class AtelierController {
  private final PrixService prix;
  AtelierController(PrixService prix) { this.prix = prix; }
  @GetMapping("/total-demo") int total() { return prix.total(5, 3); }
}
